//! UniFFI surface for [`md2wx::render`].
//!
//! The scaffolding generated by UniFFI contains unsafe FFI glue. This crate
//! adds no file or network access of its own: it only copies owned strings
//! into the library and copies the result back out.

use std::fmt;

#[derive(Clone, Debug, PartialEq, Eq, uniffi::Record)]
pub struct Theme {
    pub accent: String,
    pub ink: String,
    pub muted: String,
    pub line: String,
    pub surface: String,
    pub canvas: String,
}

#[derive(Clone, Debug, PartialEq, Eq, uniffi::Record)]
pub struct RenderOptions {
    pub theme: Theme,
    /// Empty means image `src` values stay as `{{wx-img:N}}` placeholders.
    pub image_base_url: String,
}

#[derive(Clone, Debug, PartialEq, Eq, uniffi::Record)]
pub struct ImageRef {
    pub placeholder: String,
    pub path: String,
}

#[derive(Clone, Debug, PartialEq, Eq, uniffi::Record)]
pub struct Rendered {
    pub html: String,
    pub images: Vec<ImageRef>,
    pub char_count: u64,
    pub byte_len: u64,
}

#[derive(Debug, uniffi::Error)]
pub enum RenderError {
    Unsupported { kind: String, detail: String },
    Highlight { detail: String },
    Theme { detail: String },
}

impl fmt::Display for RenderError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Unsupported { kind, detail } => write!(f, "{kind}: {detail}"),
            Self::Highlight { detail } => write!(f, "highlight: {detail}"),
            Self::Theme { detail } => write!(f, "theme: {detail}"),
        }
    }
}

impl std::error::Error for RenderError {}

impl From<md2wx::Theme> for Theme {
    fn from(theme: md2wx::Theme) -> Self {
        Self {
            accent: theme.accent,
            ink: theme.ink,
            muted: theme.muted,
            line: theme.line,
            surface: theme.surface,
            canvas: theme.canvas,
        }
    }
}

impl From<Theme> for md2wx::Theme {
    fn from(theme: Theme) -> Self {
        Self {
            accent: theme.accent,
            ink: theme.ink,
            muted: theme.muted,
            line: theme.line,
            surface: theme.surface,
            canvas: theme.canvas,
        }
    }
}

impl From<md2wx::Rendered> for Rendered {
    fn from(rendered: md2wx::Rendered) -> Self {
        Self {
            html: rendered.html,
            images: rendered
                .images
                .into_iter()
                .map(|image| ImageRef {
                    placeholder: image.placeholder,
                    path: image.path,
                })
                .collect(),
            char_count: rendered.char_count as u64,
            byte_len: rendered.byte_len as u64,
        }
    }
}

impl From<md2wx::RenderError> for RenderError {
    fn from(err: md2wx::RenderError) -> Self {
        match err {
            md2wx::RenderError::Unsupported { kind, detail } => Self::Unsupported {
                kind: kind.to_string(),
                detail,
            },
            md2wx::RenderError::Highlight(detail) => Self::Highlight { detail },
            md2wx::RenderError::Theme(detail) => Self::Theme { detail },
        }
    }
}

/// The blog light theme. Same colors as [`md2wx::Theme::blog`].
#[uniffi::export]
pub fn blog_theme() -> Theme {
    md2wx::Theme::blog().into()
}

/// Render Markdown to a WeChat HTML fragment.
///
/// `markdown` is the body only. `options.theme` supplies the inline colors,
/// and `options.image_base_url` is the optional image prefix.
#[uniffi::export]
pub fn render(markdown: String, options: RenderOptions) -> Result<Rendered, RenderError> {
    let theme = md2wx::Theme::from(options.theme);
    let rust_options = md2wx::RenderOptions {
        theme: &theme,
        image_base_url: &options.image_base_url,
    };
    md2wx::render(&markdown, &rust_options)
        .map(Rendered::from)
        .map_err(RenderError::from)
}

uniffi::setup_scaffolding!("md2wx");
